parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "opportunities": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "content": {
            "type": "string",
            "description": "The opportunity statement, framed from the customer's perspective as a need, pain point, or desire"
          },
          "clips": {
            "type": "array",
            "minItems": 1,
            "items": {
              "type": "object",
              "properties": {
                "quote": {
                  "type": "string",
                  "description": "Verbatim quote from the transcript"
                },
                "start_time": {
                  "type": "number",
                  "description": "Start time in seconds from nearest transcript timestamp marker"
                },
                "end_time": {
                  "type": "number",
                  "description": "End time in seconds from nearest transcript timestamp marker"
                }
              },
              "required": ["quote", "start_time", "end_time"]
            }
          }
        },
        "required": ["content", "clips"]
      }
    }
  },
  "required": ["opportunities"]
}

parameters.jsCode:
const words = $input.first().json.transcript_object;
const MARKER_EVERY = 20; // timestamp marker every N words

const lines = [];
let currentSpeaker = null;
let wordCount = 0;
let lineWords = [];

for (const w of words) {
  // New speaker turn
  if (w.speaker !== currentSpeaker) {
    if (lineWords.length) {
      lines.push(lineWords.join(' '));
    }
    currentSpeaker = w.speaker;
    wordCount = 0;
    lineWords = [`\nS${w.speaker} [${w.start.toFixed(2)}]:`];
  }

  // Insert timestamp marker every N words
  if (wordCount > 0 && wordCount % MARKER_EVERY === 0) {
    lineWords.push(`[${w.start.toFixed(2)}]`);
  }

  lineWords.push(w.punctuated_word);
  wordCount++;
}

if (lineWords.length) {
  lines.push(lineWords.join(' '));
}

// Also pass the last word's end time so the agent knows the total duration
const lastWord = words[words.length - 1];

return {
  transcript: lines.join('').trim(),
  duration: lastWord.end,
};
